$ErrorActionPreference='Stop'
Set-StrictMode -Version Latest
function G([string[]]$a,[switch]$ok){$o=& git @a 2>&1;$c=$LASTEXITCODE;if(!$ok -and $c-ne 0){throw ("git "+($a-join" ")+" failed: "+($o-join[Environment]::NewLine))};[pscustomobject]@{c=$c;o=@($o)}}
function RepoPath {
  $c=@('C:\Users\Xxkan\mhw-mods','C:\Users\Xxkan\source\repos\mhw-mods','C:\Users\Xxkan\Documents\GitHub\mhw-mods','C:\Users\Xxkan\Desktop\mhw-mods','C:\Users\Xxkan\repos\mhw-mods')
  foreach($p in $c){if(Test-Path(Join-Path $p '.git')){$r=G @('-C',$p,'remote','get-url','origin') -ok;if($r.c-eq 0 -and (($r.o-join'')-match'fengie/mhw-mods(\.git)?$')){return $p}}}
  foreach($d in Get-ChildItem 'C:\Users\Xxkan' -Directory -Filter mhw-mods -Recurse -Depth 6 -ErrorAction SilentlyContinue){if(Test-Path(Join-Path $d.FullName '.git')){$r=G @('-C',$d.FullName,'remote','get-url','origin') -ok;if($r.c-eq 0 -and (($r.o-join'')-match'fengie/mhw-mods(\.git)?$')){return $d.FullName}}}
  throw 'repo not found'
}
function WorktreeSet($r){$s=[System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);foreach($l in (G @('-C',$r,'worktree','list','--porcelain')).o){$x=[string]$l;if($x.StartsWith('branch refs/heads/')){[void]$s.Add($x.Substring(18))}};$s}
function Safe($r,$ref){
  if((G @('-C',$r,'merge-base','--is-ancestor',$ref,'origin/main') -ok).c-eq 0){return [pscustomobject]@{safe=$true;why='ancestor';u=0}}
  if((G @('-C',$r,'diff','--quiet','origin/main',$ref) -ok).c-eq 0){return [pscustomobject]@{safe=$true;why='same-tree';u=0}}
  $ch=G @('-C',$r,'cherry','origin/main',$ref) -ok
  if($ch.c-eq 0){$ln=@($ch.o|?{![string]::IsNullOrWhiteSpace([string]$_)});$pl=@($ln|?{([string]$_).StartsWith('+ ')});if($ln.Count-gt 0 -and $pl.Count-eq 0){return [pscustomobject]@{safe=$true;why='patch-equivalent';u=0}}}
  $q=G @('-C',$r,'rev-list','--count',('origin/main..'+$ref)) -ok;$n=if($q.c-eq 0){[int]$q.o[0]}else{-1};[pscustomobject]@{safe=$false;why='unique-or-unproven';u=$n}
}
function Tip($r,$b){$q=G @('-C',$r,'ls-remote','--heads','origin',('refs/heads/'+$b)) -ok;if($q.c-ne 0 -or $q.o.Count-eq 0){return $null};$s=[string]$q.o[0];if([string]::IsNullOrWhiteSpace($s)){return $null};($s-split'\s+')[0]}
function DateUtc($r,$ref){$q=G @('-C',$r,'show','-s','--format=%cI',$ref) -ok;if($q.c-ne 0 -or $q.o.Count-eq 0){return $null};try{[DateTimeOffset]::Parse([string]$q.o[0]).ToUniversalTime()}catch{$null}}

$r=RepoPath
$req=@('AGENTS.md','GLOBAL_GIT_DIRECTIVE.md','NEXT-AGENT-START-HERE.md','_AGENT_CONTEXT/CURRENT_REVISION.json','_AGENT_CONTEXT/CONTINUITY_PROTOCOL.md','_AGENT_CONTEXT/LEARNED_RULES.md','_AGENT_CONTEXT/README_FIRST.md')
foreach($f in $req){if(!(Test-Path(Join-Path $r $f))){throw "missing governance $f"}}
$gov=(Get-Content(Join-Path $r 'AGENTS.md')-Raw)+[Environment]::NewLine+(Get-Content(Join-Path $r 'GLOBAL_GIT_DIRECTIVE.md')-Raw)
$policy=($gov-match'main.*canonical integration branch')-and($gov-match'Delete the completed local task branch')-and($gov-match'Prune stale remote-tracking refs')
[void](G @('-C',$r,'fetch','--all','--prune'))
$base=((G @('-C',$r,'rev-parse','origin/main')).o|select -First 1).Trim()
$cur=((G @('-C',$r,'branch','--show-current')).o|select -First 1).Trim()
$def='main';$hs=G @('-C',$r,'symbolic-ref','--short','refs/remotes/origin/HEAD') -ok;if($hs.c-eq 0 -and $hs.o.Count){$z=[string]$hs.o[0];if($z.StartsWith('origin/')){$def=$z.Substring(7)}}
$wt=WorktreeSet $r
$prot=[System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
$open=[System.Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
$anom=[System.Collections.Generic.List[string]]::new();$ghok=$false
if(Get-Command gh -ErrorAction SilentlyContinue){& gh auth status *> $null;if($LASTEXITCODE-eq 0){$ghok=$true;try{$j=((& gh api --paginate 'repos/fengie/mhw-mods/branches?per_page=100')-join[Environment]::NewLine)|ConvertFrom-Json;foreach($b in @($j)){if($b.protected){[void]$prot.Add([string]$b.name)}}}catch{$anom.Add('branch protection query failed')};try{$j=((& gh pr list --repo fengie/mhw-mods --state open --limit 300 --json number,headRefName,baseRefName,title)-join[Environment]::NewLine)|ConvertFrom-Json;foreach($p in @($j)){[void]$open.Add([string]$p.headRefName);if($p.baseRefName-ne'main'){$anom.Add("open PR #$($p.number) targets $($p.baseRefName)")}}}catch{$anom.Add('open PR query failed')}}else{$anom.Add('gh not authenticated')}}else{$anom.Add('gh unavailable')}
$remote=@((G @('-C',$r,'for-each-ref','--format=%(refname:strip=3)','refs/remotes/origin')).o|?{$_ -and $_ -ne'HEAD'}|sort -Unique)
$local=@((G @('-C',$r,'for-each-ref','--format=%(refname:strip=2)','refs/heads')).o|?{$_}|sort -Unique)
$dl=[System.Collections.Generic.List[string]]::new();$dr=[System.Collections.Generic.List[string]]::new();$pa=[System.Collections.Generic.List[object]]::new();$pu=[System.Collections.Generic.List[object]]::new()
$cut=[DateTimeOffset]::UtcNow.AddHours(-2)
[void](G @('-C',$r,'fetch','origin','--prune'));$base=((G @('-C',$r,'rev-parse','origin/main')).o|select -First 1).Trim()
foreach($bx in $remote){
 $b=[string]$bx
 if($b-eq'main' -or $b-eq$def){$pa.Add([pscustomobject]@{branch=$b;reason='canonical/default'});continue}
 if($b-eq'heaven-bridge'){$pa.Add([pscustomobject]@{branch=$b;reason='live bridge transport'});continue}
 if($b.StartsWith('release/')){$pa.Add([pscustomobject]@{branch=$b;reason='release branch'});continue}
 if($wt.Contains($b)){$pa.Add([pscustomobject]@{branch=$b;reason='worktree active'});continue}
 if($open.Contains($b)){$pa.Add([pscustomobject]@{branch=$b;reason='open PR head'});continue}
 if($prot.Contains($b)){$pa.Add([pscustomobject]@{branch=$b;reason='protected'});continue}
 if(!$ghok){$pu.Add([pscustomobject]@{branch=$b;reason='cannot prove protection/open PR status'});continue}
 $ref='refs/remotes/origin/'+$b;$tip=((G @('-C',$r,'rev-parse',$ref)).o|select -First 1).Trim();$d=DateUtc $r $ref
 if($null-ne$d -and $d-gt$cut){$pa.Add([pscustomobject]@{branch=$b;reason=('recent activity '+$d.ToString('o'))});continue}
 $s=Safe $r $ref;if(!$s.safe){$pa.Add([pscustomobject]@{branch=$b;reason=($s.why+' unique_count='+$s.u)});continue}
 $live=Tip $r $b;if($null-eq$live){continue};if($live-ne$tip){$pu.Add([pscustomobject]@{branch=$b;reason='remote tip moved during cleanup'});continue}
 if($local-contains$b){if($b-eq$cur -or $wt.Contains($b)){$pa.Add([pscustomobject]@{branch=$b;reason='current/worktree local'});continue};$x=G @('-C',$r,'branch','-D','--',$b) -ok;if($x.c-eq 0){$dl.Add($b)}else{$pu.Add([pscustomobject]@{branch=$b;reason='local delete failed'});continue}}
 $x=G @('-C',$r,'push','origin',(':refs/heads/'+$b)) -ok;if($x.c-eq 0){$dr.Add($b)}else{$pu.Add([pscustomobject]@{branch=$b;reason=('remote delete failed '+($x.o-join' '))})}
}
$rn=@((G @('-C',$r,'for-each-ref','--format=%(refname:strip=3)','refs/remotes/origin')).o|?{$_ -and $_ -ne'HEAD'}|sort -Unique)
foreach($bx in $local){$b=[string]$bx;if($b-eq'main' -or $b-eq$def -or $b-eq$cur -or $wt.Contains($b) -or $dl.Contains($b) -or ($rn-contains$b)){continue};$d=DateUtc $r ('refs/heads/'+$b);if($null-ne$d -and $d-gt$cut){$pa.Add([pscustomobject]@{branch=$b;reason='local-only recent'});continue};$s=Safe $r ('refs/heads/'+$b);if($s.safe){$x=G @('-C',$r,'branch','-D','--',$b) -ok;if($x.c-eq 0){$dl.Add($b)}else{$pu.Add([pscustomobject]@{branch=$b;reason='local-only delete failed'})}}else{$pa.Add([pscustomobject]@{branch=$b;reason=('local-only '+$s.why+' unique_count='+$s.u)})}}
$pr=G @('-C',$r,'remote','prune','origin') -ok;[void](G @('-C',$r,'fetch','origin','--prune') -ok)
$final=((G @('-C',$r,'rev-parse','origin/main')).o|select -First 1).Trim()
$fl=@((G @('-C',$r,'for-each-ref','--format=%(refname:strip=2)','refs/heads')).o|?{$_}|sort -Unique);$fr=@((G @('-C',$r,'for-each-ref','--format=%(refname:strip=3)','refs/remotes/origin')).o|?{$_ -and $_ -ne'HEAD'}|sort -Unique)
[ordered]@{host=$env:COMPUTERNAME;repo=$r;baseline_origin_main=$base;final_origin_main=$final;default_branch=$def;current_branch=$cur;gh_authenticated=$ghok;governance_policy_already_present=$policy;governance_modified=$false;deleted_local=@($dl|sort -Unique);deleted_remote=@($dr|sort -Unique);preserved_unique_or_active=@($pa);preserved_unproven=@($pu);stale_refs_prune_output=@($pr.o);anomalies=@($anom);final_local_branches=$fl;final_remote_branches=$fr;worktree_branches=@($wt);no_known_unique_work_destroyed=$true;evidence=@('fetch/prune before cleanup','main/default/current/worktree/release/bridge/protection/open-PR checks','merge-base ancestry + same-tree + git cherry patch-equivalence + unique count','recent-activity preservation','ls-remote race check immediately before delete','final prune/fetch')}|ConvertTo-Json -Depth 7
